//! Offset estimate against one authority, from four-timestamp probes.
//!
//! The estimate belongs to one [`AuthKey`]. A different key (a new coordinator epoch or
//! holder) drops every sample and every probe in flight, so a pong generated by the old
//! holder can never be paired with a ping meant for the new one.

use std::collections::BTreeMap;

use crate::wire::{AuthKey, Probe};

/// Samples older than this stop counting (bounds the damage of a rate error between
/// two machines' clocks: at 200 ppm, 30 s is 6 ms).
pub const WINDOW_US: u64 = 30_000_000;
const MAX_SAMPLES: usize = 16;
const MAX_PENDING: usize = 8;

#[derive(Clone, Copy, Debug)]
struct Sample {
    taken_us: u64,
    rtt_us: i64,
    /// authority clock minus local clock
    offset_us: i64,
}

#[derive(Debug, Default)]
pub struct Estimator {
    key: Option<AuthKey>,
    samples: Vec<Sample>,
    pending: BTreeMap<u32, (AuthKey, u64)>,
    next_id: u32,
    /// Test-only: accept pongs whatever their key, and keep state across key changes.
    pub ignore_epoch: bool,
}

impl Estimator {
    /// Rekey. Returns true when the key changed (and all state was dropped).
    pub fn set_key(&mut self, key: Option<AuthKey>) -> bool {
        if self.key == key {
            return false;
        }
        self.key = key;
        if !self.ignore_epoch {
            self.samples.clear();
            self.pending.clear();
        }
        true
    }

    pub fn key(&self) -> Option<AuthKey> {
        self.key
    }

    /// Start a probe; returns the ping to send, if there is a key.
    pub fn ping(&mut self, now_us: u64) -> Option<Probe> {
        let key = self.key?;
        self.next_id = self.next_id.wrapping_add(1);
        let id = self.next_id;
        self.pending.insert(id, (key, now_us));
        while self.pending.len() > MAX_PENDING {
            let first = *self.pending.keys().next().unwrap();
            self.pending.remove(&first);
        }
        Some(Probe::Ping {
            id,
            key,
            t1_us: now_us,
        })
    }

    /// Feed a pong received at local time `t4`. Returns whether it became a sample.
    pub fn pong(&mut self, t4: u64, p: &Probe) -> bool {
        let Probe::Pong {
            id,
            key,
            t1_us,
            t2_us,
            t3_us,
        } = *p
        else {
            return false;
        };
        let Some((pkey, sent)) = self.pending.remove(&id) else {
            return false;
        };
        if !self.ignore_epoch && (Some(key) != self.key || pkey != key) {
            return false;
        }
        if sent != t1_us || t4 < t1_us || t3_us < t2_us {
            return false;
        }
        let rtt = (t4 - t1_us) as i64 - (t3_us - t2_us) as i64;
        if rtt < 0 {
            return false;
        }
        let offset = ((t2_us as i64 - t1_us as i64) + (t3_us as i64 - t4 as i64)) / 2;
        self.samples.push(Sample {
            taken_us: t4,
            rtt_us: rtt,
            offset_us: offset,
        });
        if self.samples.len() > MAX_SAMPLES {
            self.samples.remove(0);
        }
        true
    }

    /// Authority clock minus local clock, from the lowest-RTT sample inside the window.
    pub fn offset_us(&self, now_us: u64) -> Option<i64> {
        self.samples
            .iter()
            .filter(|s| now_us.saturating_sub(s.taken_us) <= WINDOW_US)
            .min_by_key(|s| s.rtt_us)
            .map(|s| s.offset_us)
    }

    pub fn best_rtt_us(&self, now_us: u64) -> Option<i64> {
        self.samples
            .iter()
            .filter(|s| now_us.saturating_sub(s.taken_us) <= WINDOW_US)
            .map(|s| s.rtt_us)
            .min()
    }

    pub fn has_samples(&self) -> bool {
        !self.samples.is_empty()
    }

    pub fn last_sample_us(&self) -> Option<u64> {
        self.samples.last().map(|s| s.taken_us)
    }
}
